    {"ref": 4, "underlying_study": "2025 short review of creatine supplementation safety concerns"},
    {"ref": 5, "underlying_study": "Kreider et al. 2017 ISSPN position stand"}
  ],
  "conditions": [
    {"id": "C1", "text": "The populations in the cited studies consist of healthy adults without pre-existing renal conditions, matching the conclusion's target demographic."},
    {"id": "C2", "text": "The dosing regimens and supplementation durations investigated in the cited studies adequately cover the 'standard doses' and 'long-term' periods referenced in the conclusion."},
    {"id": "C3", "text": "The renal biomarkers used in the cited studies (e.g., serum creatinine, estimated GFR, cystatin C) accurately reflect true kidney health and are not confounded by creatine metabolism."},
    {"id": "C4", "text": "The absence of clinically significant changes in renal markers in the cited trials implies a lack of actual kidney damage, rather than merely a failure to detect it due to study limitations."},
    {"id": "C5", "text": "Clinical guidelines for interpreting elevated creatinine (e.g., using cystatin C or clinical context) effectively prevent misdiagnosis, supporting the safety claim despite the biomarker elevation."}
  ],
  "unstated": [
    {"id": "U1", "text": "Systematic reviews, meta-analyses, and professional position stands accurately synthesize primary research and provide reliable evidence of safety."},
    {"id": "U2", "text": "The absence of reported renal impairment in controlled trials and observational studies constitutes evidence of physiological safety rather than merely an absence of detected harm."}
  ],
  "routes": [
    {
      "route": 1,
      "refs": [1, 2],
      "conditions": ["C2", "C3", "U1", "U2"],
      "summary": "Two systematic reviews and meta-analyses directly conclude that creatine supplementation causes no renal harm in healthy adults at studied doses and durations."
    },
    {
      "route": 2,
      "refs": [3, 4],
      "conditions": ["C2", "C3", "C5", "U1", "U2"],
      "summary": "Long-term observational data and a broad safety review confirm no clinically significant marker changes across wide dose and duration ranges, while clarifying that creatinine elevation does not indicate damage."
    },
    {
      "route": 3,
      "refs": [4, 5],
      "conditions": ["C1", "C2", "U1", "U2"],
      "summary": "A comprehensive safety review and professional consensus establish that creatine does not cause kidney dysfunction in healthy individuals, including at high doses and long durations."
    }
  ]
}

