  "conclusion": "Intermittent fasting does not consistently produce more weight loss than continuous calorie restriction in adults, as both approaches yield similar weight loss when energy intake is comparable, with only alternate-day fasting showing a modest short-term advantage.",
  "references": [
    {
      "ref": 1,
      "underlying_study": "Yu 2025 BMJ network meta-analysis"
    },
    {
      "ref": 2,
      "underlying_study": "Obesity 2024 systematic review and meta-analysis"
    },
    {
      "ref": 3,
      "underlying_study": "Allaf 2021 Cochrane review"
    },
    {
      "ref": 4,
      "underlying_study": "BMC Endocrine Disorders 2018 meta-analysis"
    },
    {
      "ref": 5,
      "underlying_study": "IJBNPA 2024 network meta-analysis"
    }
  ],
  "conditions": [
    {
      "id": "C1",
      "text": "The trial participants (predominantly overweight/obese adults) are representative of the general adult population to which the conclusion applies."
    },
    {
      "id": "C2",
      "text": "The fasting and continuous restriction protocols in the trials accurately reflect standard implementations of these dietary approaches."
    },
    {
      "id": "C3",
      "text": "A weight loss difference of approximately 1 kg is below the threshold for clinical significance, requiring an assumed cutoff to dismiss superiority."
    },
    {
      "id": "C4",
      "text": "The cited trials adequately matched or controlled for total energy intake, ensuring that comparable caloric deficits produce comparable weight loss."
    },
    {
      "id": "C5",
      "text": "Follow-up durations of 3–12 months are sufficient to assess long-term efficacy and rule out sustained superiority."
    },
    {
      "id": "C6",
      "text": "Metabolic adaptations to fasting are negligible compared to the effects of total energy deficit and adherence, requiring that metabolic confounders were adequately controlled."
    }
  ],
  "unstated": [
    {
      "id": "U1",
      "text": "Systematic reviews and meta-analyses of randomized controlled trials provide reliable, generalizable evidence for dietary intervention efficacy."
    },
    {
      "id": "U2",
      "text": "Weight loss magnitude is the sole or primary metric for determining the clinical superiority of a weight-loss strategy."
    }
  ],
  "routes": [
    {
      "route": 1,
      "refs": [2, 3, 4],
      "conditions": ["C1", "C2", "C3", "C4", "C5", "U1", "U2"],
      "summary": "Multiple direct comparative reviews show IF and CR yield statistically similar weight loss over 3–12 months, supporting the claim that IF does not consistently outperform CR when energy intake is comparable."
