      "underlying_study": "2021 systematic review and meta-analysis of randomized controlled trials on melatonin supplementation and sleep quality"
    },
    {
      "ref": 5,
      "underlying_study": "2022 systematic review and meta-analysis of melatonin and/or ramelteon for insomnia in older adults"
    },
    {
      "ref": 6,
      "underlying_study": "2021 American Academy of Family Physicians clinical overview on melatonin to treat insomnia in older adults"
    },
    {
      "ref": 7,
      "underlying_study": "2017 American Academy of Sleep Medicine clinical practice guideline for the pharmacologic treatment of chronic insomnia in adults"
    },
    {
      "ref": 8,
      "underlying_study": "2026 National Center for Complementary and Integrative Health report on sleep disorders and complementary health approaches"
    }
  ],
  "conditions": [
    {
      "id": "C1",
      "text": "The adult populations with chronic insomnia in the 2022 and 2020 systematic reviews (Refs 1, 2) are clinically representative of the general target population."
    },
    {
      "id": "C2",
      "text": "The heterogeneous medical conditions and inclusion of primary sleep disorders in Refs 3 and 4 prevent their positive findings from reliably generalizing to adults with chronic insomnia."
    },
    {
      "id": "C3",
      "text": "The observed benefits in older adults or with prolonged-release formulations (Refs 5, 6) do not apply to immediate-release, over-the-counter melatonin for the general adult population."
