    {
      "id": "C4",
      "text": "The clinical guidelines (Refs 7, 8) accurately reflect the current body of evidence and their recommendations against routine use are directly supported by the cited trials."
    },
    {
      "id": "C5",
      "text": "The effect sizes and outcomes reported in the meta-analyses align with established thresholds for clinically important improvement in sleep quality."
    }
  ],
  "unstated": [
    {
      "id": "U1",
      "text": "Systematic reviews, meta-analyses, and professional clinical guidelines provide a valid and reliable basis for determining treatment efficacy and standard-of-care recommendations."
