    {
      "route": 2,
      "refs": [3, 4],
      "conditions": ["C2", "U1"],
      "summary": "Older or broader meta-analyses reporting positive effects are excluded from supporting efficacy claims because their diverse populations prevent generalization to the specific target group."
    },
    {
      "route": 3,
      "refs": [5, 6],
      "conditions": ["C3", "U1"],
      "summary": "Evidence of benefits in older adults or with prolonged-release formulations is shown to be non-generalizable to immediate-release over-the-counter melatonin for the general adult population, reinforcing the conclusion."
    },
    {
      "route": 4,
      "refs": [7, 8],
      "conditions": ["C4", "U1"],
      "summary": "Major clinical guidelines explicitly recommend against routine melatonin use for chronic insomnia in adults, corroborating the evidence-based conclusion through professional consensus."
    }
  ]
